questions.solution:
function slugify(text) {
  const slug = text
    .normalize("NFKD")
    .replace(/\p{M}/gu, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
  return slug || "product";
}

console.log(slugify("Ìyá Àkàrà"));
console.log(slugify("Fish & Chips (Large)"));
console.log(slugify("🍲🍲"));

