questions.solution:
const escape = (value) =>
  String(value).replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;").replaceAll('"', "&quot;");

function html(strings, ...values) {
  return strings.reduce((out, text, i) => out + escape(values[i - 1]) + text);
}

const name = 'Suya <b>"hot"</b> & spicy';
console.log(html`<p class="item">${name}</p>`);

