function cleanName(raw) {
  return String(raw).toWellFormed().normalize("NFC").replace(/\s+/g, " ").trim();
}

console.log(JSON.stringify([
  cleanName("  Rice \t 5kg "),
  cleanName("Café").length,
  cleanName("Pot \ud83c"),
]));

